    type: {
      type: String, // incomeAmount || pledgeAmount TODO validator
      default: null
    },
    amount: {
      type: Number,
      default: null
    }
  },
  computed: {
    ...mapGetters([
      'groupSettings',
      'groupProfiles',
      'currentPaymentPeriod',
      'haveNeedsForThisPeriod',
      'ourIdentityContractId'
